<template><main class="container page-section"><div class="heading"><div><p class="eyebrow">Creation</p><h1 class="page-title">创作中心</h1><p class="muted">管理文章、草稿和发布状态。</p></div><RouterLink class="button button-primary" to="/write"><AppIcon name="pen" :size="17"/>写文章</RouterLink></div><div class="stats"><div class="card"><b>{{stats.total||0}}</b><span>全部文章</span></div><div class="card"><b>{{stats.drafts||0}}</b><span>草稿</span></div><div class="card"><b>{{stats.published||0}}</b><span>已发布</span></div><div class="card"><b>{{stats.views||0}}</b><span>累计阅读</span></div></div><div v-if="!items.length" class="empty">还没有文章。先写下第一个草稿吧。</div><div v-else class="articles"><article v-for="post in filtered" :key="post.id" class="card"><div><small>{{post.status}} · 更新于 {{date(post.updated_at)}}</small><h2>{{post.title}}</h2><p class="muted">{{post.excerpt||post.content_markdown.slice(0,100)}}</p></div><div class="row"><RouterLink class="button" :to="`/posts/${post.id}/edit`">编辑</RouterLink><RouterLink v-if="post.status==='published'" class="button" :to="`/posts/${post.slug}`">查看</RouterLink></div></article></div></main></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useRoute,RouterLink}from'vue-router';import http from'@/services/http';import AppIcon from'@/components/AppIcon.vue';const route=useRoute(),items=ref<any[]>([]),stats=ref<any>({});const filtered=computed(()=>route.query.status==='draft'?items.value.filter(p=>p.status==='draft'):items.value);const date=(v:string)=>new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium'}).format(new Date(v));onMounted(async()=>{try{[items.value,stats.value]=[(await http.get('/api/posts')).data.items,(await http.get('/api/dashboard/overview')).data.stats]}catch{}})</script>
<style scoped>.heading,.row{display:flex;justify-content:space-between;align-items:center;gap:12px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:28px 0}.stats div{padding:18px;display:grid;gap:4px}.stats b{font-size:1.7rem}.stats span,small{color:var(--muted)}.articles{display:grid;gap:10px}.articles article{padding:18px;display:flex;justify-content:space-between;gap:20px}.articles h2{font-size:1.15rem;margin:4px 0}@media(max-width:640px){.stats{grid-template-columns:repeat(2,1fr)}.articles article{display:block}.row{margin-top:12px;justify-content:start}}</style>
